const ESCAPES = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
};

// Escapes the five HTML-significant characters, preserving all other
// code points (including Unicode) verbatim.
export function escapeHtml(text) {
  return String(text).replace(/[&<>"]/g, (ch) => ESCAPES[ch]);
}

export function renderField(label, value, id) {
  const safeLabel = escapeHtml(label);
  const safeValue = escapeHtml(value);
  const safeId = escapeHtml(id);
  return `<label for="${safeId}">${safeLabel}</label>` +
    `<input id="${safeId}" type="text" value="${safeValue}">`;
}

export function canRead(actor, document) {
  if (!actor || !document) return false;
  if (actor.active !== true) return false;
  if (actor.tenantId !== document.tenantId) return false;
  if (actor.role === 'admin') return true;
  if (actor.role === 'member') return actor.userId === document.ownerId;
  return false;
}

const JSON_HEADERS = {'content-type': 'application/json'};

const fail = (status, error) => ({status, body: {error}, headers: JSON_HEADERS});

export function parseRequest(req) {
  if (req.method !== 'POST') return fail(405, 'method');

  const mime = String(req.contentType ?? '').split(';')[0].trim().toLowerCase();
  if (mime !== 'application/json') return fail(415, 'content-type');

  let payload;
  try {
    payload = JSON.parse(req.body);
  } catch {
    return fail(400, 'body');
  }

  if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
    return fail(400, 'body');
  }

  const name = typeof payload.name === 'string' ? payload.name.trim() : '';
  if (!name) return fail(400, 'body');

  return {status: 201, body: {name}, headers: JSON_HEADERS};
}

export function migrate(record) {
  if (record.version === 2) return record;
  if (record.version !== 1) throw new Error('Unsupported version');
  const {fullName, ...rest} = record;
  return {...rest, displayName: fullName, version: 2};
}

const CHINESE = new Set(['zh', 'zh-CN']);

export function fileCount(locale, count) {
  if (CHINESE.has(locale)) return `${count} 个文件`;
  return count === 1 ? '1 file' : `${count} files`;
}

import path from 'node:path';

export function isWithin(root, candidate) {
  const rel = path.relative(path.resolve(root), path.resolve(candidate));
  return rel === '' || (!rel.startsWith('..') && !path.isAbsolute(rel));
}

export function indexById(records, ids) {
  const index = new Map();
  for (const record of records) {
    if (!index.has(record.id)) index.set(record.id, record);
  }
  return ids.map(id => index.get(id));
}

// Behavioral regression checker for an add(a, b) implementation over small integers.
// Probes the public function across cases that distinguish real addition from
// common wrong behaviours: off-by-one, absolute value, multiplication,
// constant-zero, and throwing.
const CASES = [
  [0, 0],       // zero
  [1, 1],       // more than one positive sum
  [2, 3],
  [3, 2],
  [-4, 1],      // mixed signs, positive sum
  [4, -1],      // mixed signs, positive sum (order-sensitive)
  [-4, -6],     // negative sum
  [-7, 2],      // mixed signs, negative sum
  [1, -1],      // sum is exactly zero
];

export function checkAdder(add) {
  if (typeof add !== 'function') return false;
  for (const [a, b] of CASES) {
    let result;
    try {
      result = add(a, b);
    } catch {
      return false;
    }
    if (result !== a + b) return false;
  }
  return true;
}

