// NaN and -0 are excluded/aliased so that lookups keep strict `===` semantics:
// a Map alone would match NaN to NaN and would collapse -0 onto 0.
const NO_NAN = Symbol('no-nan');
const NEG_ZERO = Symbol('neg-zero');

function indexKeyOf(id) {
  if (id !== id) return NO_NAN;
  if (id === 0) return NEG_ZERO;
  return id;
}

export function indexById(records, ids) {
  if (ids.length === 0) return [];

  const index = new Map();
  for (let i = 0; i < records.length; i++) {
    const record = records[i];
    const key = indexKeyOf(record.id);
    if (key === NO_NAN) continue;
    if (!index.has(key)) index.set(key, record);
  }

  return ids.map(id => {
    const key = indexKeyOf(id);
    if (key === NO_NAN) return undefined;
    const found = index.get(key);
    return found === undefined ? undefined : found;
  });
}

