import path from 'node:path';

export function isWithin(root, candidate) {
  const base = stripTrailingSep(path.posix.normalize(root));
  const target = path.posix.normalize(candidate);
  if (base === path.posix.sep) return target.startsWith(path.posix.sep);
  if (target === base) return true;
  return target.startsWith(base + path.posix.sep);
}

function stripTrailingSep(p) {
  return p.length > 1 ? p.replace(/\/+$/, '') : p;
}

const PROBES = [
  [0, 0],
  [0, 5],
  [5, 0],
  [2, 3],
  [4, 7],
  [-2, -3],
  [-4, 2],
  [3, -8],
  [-1, -1],
  [10, -10],
];

export function checkAdder(add) {
  if (typeof add !== 'function') return false;
  for (const [a, b] of PROBES) {
    let result;
    try {
      result = add(a, b);
    } catch {
      return false;
    }
    if (typeof result !== 'number' || !Number.isFinite(result) || result !== a + b) {
      return false;
    }
  }
  return true;
}

