import { posix } from 'node:path';

// Lexical containment check for absolute POSIX paths.
// No filesystem reads: this is a pure string/segment check, so it makes no
// claim about symlink containment (that needs a realpath-based check).
export function isWithin(root, candidate) {
  const normalizedRoot = posix.normalize(root);
  const normalizedCandidate = posix.normalize(candidate);

  if (normalizedCandidate === normalizedRoot) return true;
  if (normalizedRoot === '/') return normalizedCandidate.startsWith('/');

  const prefix = normalizedRoot.endsWith('/')
    ? normalizedRoot
    : `${normalizedRoot}/`;
  return normalizedCandidate.startsWith(prefix);
}

export function indexById(records, ids) {
  if (ids.length === 0) return [];
  const index = new Map();
  for (const record of records) {
    const id = record.id;
    // NaN never satisfies strict ===, so it is never a matchable key.
    if (id !== id) continue;
    if (!index.has(id)) index.set(id, record);
  }
  return ids.map(id => (id === id ? index.get(id) : undefined));
}

