  [0, 0],
  [0, 7],
  [3, 4],
  [2, 5],
  [1, 9],
  [5, -2],
  [-3, 8],
  [-4, -6],
];

export function checkAdder(add) {
  for (const [a, b] of CASES) {
    let actual;
    try {
      actual = add(a, b);
    } catch {
      return false;
    }
    if (actual !== a + b) return false;
  }
  return true;
}

